JET_IMAGE_BASE64 = """"""

# 1페이지 평면 세계지도용 국가 경계 (gzip + base64로 코드에 내장)
WORLD_GEOJSON_BASE64 = """"""


@st.cache_resource
def load_world_geojson():
    geojson = json.loads(
        gzip.decompress(
            base64.b64decode(WORLD_GEOJSON_BASE64)
        ).decode("utf-8")
    )

    ids = [
        feature.get("id")
        for feature in geojson.get("features", [])
        if feature.get("id")
    ]

    return geojson, ids

