def go_to_page(page_key):
    """페이지를 바꾸고, 새 화면을 맨 위에서 시작하도록 표시합니다."""
    st.session_state.app_page = page_key
    st.session_state.scroll_to_top = True
    st.rerun()


def scroll_to_top_script():
    """
    Streamlit은 rerun 후에도 스크롤 위치를 유지하므로
    페이지 이동 직후에만 맨 위로 올려 줍니다.
    components.html은 iframe 안에서 실행되어 parent 문서를 조작합니다.
    """
    components.html(
        """
        <script>
        const doc = window.parent.document;

        const scrollTop = () => {
            const targets = [
                doc.querySelector('section.stMain'),
                doc.querySelector('[data-testid="stMain"]'),
                doc.querySelector('section.main'),
                doc.querySelector('[data-testid="stAppViewContainer"]'),
                doc.scrollingElement,
                doc.documentElement,
                doc.body,
            ];
            for (const t of targets) {
                if (!t) continue;
                try { t.scrollTo({ top: 0, behavior: 'auto' }); }
                catch (e) { t.scrollTop = 0; }
            }
        };

        scrollTop();
        requestAnimationFrame(scrollTop);
        setTimeout(scrollTop, 60);
        setTimeout(scrollTop, 200);
        </script>
        """,
        height=0,
    )


def image_to_data_uri(path):
    path = Path(path)
    if not path.exists():
        return ""
    suffix = path.suffix.lower().replace(".", "")
    if suffix == "jpg":
        suffix = "jpeg"
    encoded = base64.b64encode(path.read_bytes()).decode("utf-8")
    return f"data:image/{suffix};base64,{encoded}"


