# current_usd / gdp_calculated 는 '백만 USD' 단위입니다.
def usd_m_text(value):
    if pd.isna(value):
        return "-"

    value = float(value)
    size = abs(value)

    if size >= 1_000_000:
        return f"${value / 1_000_000:.2f}T"

    if size >= 1_000:
        return f"${value / 1_000:.1f}B"

    return f"${value:,.0f}M"


