def render_page1():

    # ============================================================
    # 2. HTML 출력 함수
    # ============================================================

    def p1_html(code):
        code = dedent(code).strip()

        if hasattr(st, "html"):
            st.html(code)
        else:
            st.markdown(code, unsafe_allow_html=True)


    # ============================================================
    # 3. 파일 경로
    # ============================================================

    BASE_DIR = Path(__file__).resolve().parent
    DATA_PATH = BASE_DIR / "Integrate_new.csv"


    # ============================================================
    # 4. 상단 실제 제트기 이미지
    #
    # 이미지가 코드 안에 내장되어 있으므로
    # assets 폴더 / 이미지 파일 / 인터넷 연결이 필요하지 않습니다.
    # ============================================================



    # ============================================================
    # 4-1. 평면 세계지도용 국가 경계 데이터
    #
    # - 코드 안에 압축해서 내장
    # - 별도 GeoJSON 파일 필요 없음
    # - MapLibre 기반 평면 지도에서 좌우로 이동할 때
    #   세계가 반복되어 반대편 지역이 이어서 보이게 하기 위함
    # ============================================================


    WORLD_GEOJSON, WORLD_GEOJSON_IDS = load_world_geojson()


    # ============================================================
    # 5. 프로젝트 설정
    # ============================================================

    HIGH_RISK_THRESHOLD = 7.0

    # 현재 current_usd가 SIPRI의 million USD 단위인 경우 True
    MILITARY_VALUES_ARE_MILLION_USD = True


    # ============================================================
    # 6. CSV 데이터 불러오기
    # ============================================================

    def load_data():
        # 2·3페이지와 같은 공용 로더 (AWS DB integrate 테이블, 없으면 CSV)
        return load_integrate_raw()[0]


    df = load_data()


    # ============================================================
    # 7. 실제 CSV 컬럼
    # ============================================================

    COUNTRY_COL = "Country"
    ISO_COL = "Iso3"
    YEAR_COL = "Year"

    MIL_COL = "current_usd"
    GDP_COL = "gdp_calculated"

    TIV_SHARE_COL = "TIV_5Y_Share"
    TIV_SUM_COL = "TIV_5Y_Sum"

    RISK_COL = "human_hazard_score"
    SHARE_GDP_COL = "share_gdp"


    # ============================================================
    # 8. 필요한 컬럼 확인
    # ============================================================

    required_columns = [
        COUNTRY_COL,
        ISO_COL,
        YEAR_COL,
        MIL_COL,
        GDP_COL,
        TIV_SHARE_COL,
        TIV_SUM_COL,
        RISK_COL,
        SHARE_GDP_COL,
    ]

    missing_columns = [col for col in required_columns if col not in df.columns]

    if missing_columns:
        st.error("CSV에 필요한 컬럼이 없습니다.")
        st.write("없는 컬럼:", missing_columns)
        st.write("현재 CSV 컬럼:", df.columns.tolist())
        st.stop()


    # ============================================================
    # 9. 숫자형 변환
    # ============================================================

    numeric_columns = [
        YEAR_COL,
        MIL_COL,
        GDP_COL,
        TIV_SHARE_COL,
        TIV_SUM_COL,
        RISK_COL,
        SHARE_GDP_COL,
    ]

    for col in numeric_columns:
        df[col] = pd.to_numeric(df[col], errors="coerce")

    df = df.dropna(
        subset=[
            COUNTRY_COL,
            ISO_COL,
            YEAR_COL,
        ]
    ).copy()

    df[YEAR_COL] = df[YEAR_COL].astype(int)

    df[ISO_COL] = (
        df[ISO_COL]
        .astype(str)
        .str.upper()
        .str.strip()
    )


    # ============================================================
    # 10. 단위/표시 함수
    # ============================================================

    def military_to_usd(value):
        if pd.isna(value):
            return np.nan

        value = float(value)

        if MILITARY_VALUES_ARE_MILLION_USD:
            return value * 1_000_000

        return value


    def money_format(value):
        if pd.isna(value):
            return "-"

        value = float(value)

        if abs(value) >= 1_000_000_000_000:
            return f"${value / 1_000_000_000_000:.2f}T"

        if abs(value) >= 1_000_000_000:
            return f"${value / 1_000_000_000:.1f}B"

        if abs(value) >= 1_000_000:
            return f"${value / 1_000_000:.1f}M"

        if abs(value) >= 1_000:
            return f"${value / 1_000:.1f}K"

        return f"${value:,.0f}"


    def tiv_format(value):
        if pd.isna(value):
            return "-"

        value = float(value)

        if abs(value) >= 1_000_000:
            return f"{value / 1_000_000:.1f}M"

        if abs(value) >= 1_000:
            return f"{value / 1_000:.1f}K"

        return f"{value:,.1f}"


    # ============================================================
    # 11. 무기 수입 점유율 단위 판단
    # ============================================================

    tiv_share_values = df[TIV_SHARE_COL].dropna().abs()

    if not tiv_share_values.empty:
        TIV_SHARE_IS_FRACTION = tiv_share_values.quantile(0.95) <= 1
    else:
        TIV_SHARE_IS_FRACTION = False


    def tiv_share_format(value):
        if pd.isna(value):
            return "-"

        value = float(value)

        if TIV_SHARE_IS_FRACTION:
            value *= 100

        return f"{value:.2f}%"


    # ============================================================
    # 12. GDP 대비 군사비 비율
    # ============================================================

    def share_gdp_to_percent(series):
        result = series.dropna().copy()

        if result.empty:
            return result

        if result.abs().median() <= 1:
            result *= 100

        return result


    # ============================================================
    # 13. KPI 전년 대비
    #
    # 증가 = 빨강
    # 감소 = 초록
    # 동일 = 회색
    # ============================================================

    def percent_delta(current, previous):
        if (
            pd.isna(current)
            or pd.isna(previous)
            or previous == 0
        ):
            return "전년 데이터 없음", "neutral"

        if np.isclose(
            current,
            previous,
            rtol=1e-9,
            atol=1e-12,
        ):
            return "● 전년과 동일", "same"

        change = (
            (current - previous)
            / abs(previous)
            * 100
        )

        # 화면에서 0.0%로 보일 정도의 차이도 동일 처리
        if abs(change) < 0.05:
            return "● 전년과 동일", "same"

        if change > 0:
            return f"▲ 전년 대비 +{change:.1f}%", "up"

        return f"▼ 전년 대비 {abs(change):.1f}%", "down"


    def percentage_point_delta(current, previous):
        if pd.isna(current) or pd.isna(previous):
            return "전년 데이터 없음", "neutral"

        change = current - previous

        # 화면에서 0.00%p로 보일 정도의 차이도 동일 처리
        if (
            np.isclose(
                current,
                previous,
                rtol=1e-9,
                atol=1e-12,
            )
            or abs(change) < 0.005
        ):
            return "● 전년과 동일", "same"

        if change > 0:
            return f"▲ 전년 대비 +{change:.2f}%p", "up"

        return f"▼ 전년 대비 {abs(change):.2f}%p", "down"


    def count_delta(current, previous, previous_exists):
        if not previous_exists:
            return "전년 데이터 없음", "neutral"

        change = int(current) - int(previous)

        if change == 0:
            return "● 전년과 동일", "same"

        if change > 0:
            return f"▲ 전년 대비 +{change}개국", "up"

        return f"▼ 전년 대비 {abs(change)}개국", "down"


    # ============================================================
    # 14. ISO / 한글 국가명 / 국기
    # ============================================================

    KO_LOCALE = Locale.parse("ko")

    SPECIAL_ISO2 = {
        "XKX": "XK",
    }

    SPECIAL_KOREAN_NAMES = {
        "XKX": "코소보",
    }


    def iso3_to_alpha2(iso3):
        if pd.isna(iso3):
            return None

        iso3 = str(iso3).upper()

        if iso3 in SPECIAL_ISO2:
            return SPECIAL_ISO2[iso3]

        try:
            country = pycountry.countries.get(alpha_3=iso3)

            if country:
                return country.alpha_2

        except Exception:
            pass

        return None


    def country_name_korean(iso3, fallback):
        iso3 = str(iso3).upper()

        if iso3 in SPECIAL_KOREAN_NAMES:
            return SPECIAL_KOREAN_NAMES[iso3]

        alpha2 = iso3_to_alpha2(iso3)

        if alpha2:
            korean_name = KO_LOCALE.territories.get(alpha2)

            if korean_name:
                return korean_name

        return str(fallback)


    def country_flag_html(iso3):
        """
        ISO3 -> 실제 국기 이미지 HTML
        Windows에서 국기 이모지가 문자/빈칸으로 보이는 문제를 피하기 위해
        FlagCDN의 PNG 이미지를 사용합니다.
        """
        alpha2 = iso3_to_alpha2(iso3)

        if not alpha2:
            return """
            <span class="flag-placeholder">
                🌐
            </span>
            """

        code = alpha2.lower()

        return f"""
        <img
            class="country-flag"
            src="https://flagcdn.com/w40/{code}.png"
            alt="{code.upper()}"
        >
        """


